  std::any parseTicker(std::any ticker, std::any market = std::any{}) override {
    std::any marketId = this->safeString(ticker, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    std::any timestamp = std::any{};
    std::any bid = std::any{};
    std::any ask = std::any{};
    std::any bidVolume = std::any{};
    std::any askVolume = std::any{};
    std::any baseVolume = std::any{};
    std::any quoteVolume = std::any{};
    std::any open = std::any{};
    std::any high = std::any{};
    std::any low = std::any{};
    std::any changePcnt = std::any{};
    std::any changeValue = std::any{};
    std::any prevClose = std::any{};
    std::any isSwap = this->safeValue(market, std::string("swap"));
    // if swap
    if (isTrue(isTrue((isEqual(isSwap, true))) ||
               isTrue((inOp(ticker, std::string("timestamp")))))) {
      //
      //     {
      //         "symbol": "ETH_USDT",
      //         "lastPrice": 3581.3,
      //         "bid1": 3581.25,
      //         "ask1": 3581.5,
      //         "volume24": 4045530,
      //         "amount24": 141331823.5755,
      //         "holdVol": 5832946,
      //         "lower24Price": 3413.4,
      //         "high24Price": 3588.7,
      //         "riseFallRate": 0.0275,
      //         "riseFallValue": 95.95,
      //         "indexPrice": 3580.7852,
      //         "fairPrice": 3581.08,
      //         "fundingRate": 0.000063,
      //         "maxBidPrice": 3938.85,
      //         "minAskPrice": 3222.7,
      //         "timestamp": 1634162885016
      //     }
      //
      timestamp = this->safeInteger(ticker, std::string("timestamp"));
      bid = this->safeString(ticker, std::string("bid1"));
      ask = this->safeString(ticker, std::string("ask1"));
      baseVolume = this->safeString(ticker, std::string("volume24"));
      quoteVolume = this->safeString(ticker, std::string("amount24"));
      high = this->safeString(ticker, std::string("high24Price"));
      low = this->safeString(ticker, std::string("lower24Price"));
      changeValue = this->safeString(ticker, std::string("riseFallValue"));
      changePcnt = this->safeString(ticker, std::string("riseFallRate"));
      changePcnt = ccxt::Precise::stringMul(changePcnt, std::string("100"));
    } else {
      //
      //     {
      //         "symbol": "BTCUSDT",
      //         "priceChange": "184.34",
      //         "priceChangePercent": "0.00400048",
      //         "prevClosePrice": "46079.37",
      //         "lastPrice": "46263.71",
      //         "lastQty": "",
      //         "bidPrice": "46260.38",
      //         "bidQty": "",
      //         "askPrice": "46260.41",
      //         "askQty": "",
      //         "openPrice": "46079.37",
      //         "highPrice": "47550.01",
      //         "lowPrice": "45555.5",
      //         "volume": "1732.461487",
      //         "quoteVolume": null,
      //         "openTime": 1641349500000,
      //         "closeTime": 1641349582808,
      //         "count": null
      //     }
      //
      timestamp = this->safeInteger(ticker, std::string("closeTime"));
      bid = this->safeString(ticker, std::string("bidPrice"));
      ask = this->safeString(ticker, std::string("askPrice"));
      bidVolume = this->safeString(ticker, std::string("bidQty"));
      askVolume = this->safeString(ticker, std::string("askQty"));
      if (isTrue(ccxt::Precise::stringEq(bidVolume, std::string("0")))) {
        bidVolume = std::any{};
      }
      if (isTrue(ccxt::Precise::stringEq(askVolume, std::string("0")))) {
        askVolume = std::any{};
      }
      baseVolume = this->safeString(ticker, std::string("volume"));
      quoteVolume = this->safeString(ticker, std::string("quoteVolume"));
      open = this->safeString(ticker, std::string("openPrice"));
      high = this->safeString(ticker, std::string("highPrice"));
      low = this->safeString(ticker, std::string("lowPrice"));
      prevClose = this->safeString(ticker, std::string("prevClosePrice"));
      changeValue = this->safeString(ticker, std::string("priceChange"));
      changePcnt = this->safeString(ticker, std::string("priceChangePercent"));
      changePcnt = ccxt::Precise::stringMul(changePcnt, std::string("100"));
    }
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("open"), open},
            {std::string("high"), high},
            {std::string("low"), low},
            {std::string("close"),
             this->safeString(ticker, std::string("lastPrice"))},
            {std::string("bid"), bid},
            {std::string("bidVolume"), bidVolume},
            {std::string("ask"), ask},
            {std::string("askVolume"), askVolume},
            {std::string("vwap"), std::any{}},
            {std::string("previousClose"), prevClose},
            {std::string("change"), changeValue},
            {std::string("percentage"), changePcnt},
            {std::string("average"), std::any{}},
            {std::string("baseVolume"), baseVolume},
            {std::string("quoteVolume"), quoteVolume},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name mexc#fetchBidsAsks
   * @description fetches the bid and ask price and volume for multiple markets
   * @see
   * https://www.mexc.com/api-docs/spot-v3/market-data-endpoints/symbol-order-book-ticker
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the bids and asks for, all markets are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchBidsAsks(std::any symbols = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 std::any isSingularMarket = false;
                 if (isTrue(!isEqual(symbols, std::any{}))) {
                   std::any length = getArrayLength(symbols);
                   isSingularMarket = isEqual(length, 1);
                   market = this->market(::getValue(symbols, 0));
                 }
                 std::any marketTypequeryVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchBidsAsks"), market, params);
                 std::any marketType = ::getValue(marketTypequeryVariable, 0);
                 std::any query = ::getValue(marketTypequeryVariable, 1);
                 std::any tickers = std::any{};
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   tickers =
                       awaitValue(this->spotPublicGetTickerBookTicker(query));
                 } else if (isTrue(isEqual(marketType, std::string("swap")))) {
                   throw NotSupported(toString(add(
                       add(add(this->id,
                               std::string(
                                   " fetchBidsAsks() is not available for ")),
                           marketType),
                       std::string(" markets"))));
                 }
                 // when it's single symbol request, the returned structure is
                 // different (singular object) for both spot & swap, thus we
                 // need to wrap inside array
                 if (isTrue(isSingularMarket)) {
                   tickers = ccxt::list{tickers};
                 }
                 return this->parseTickers(tickers, symbols);
               })
        .share();
  }

  /**
   * @method
   * @name mexc#createMarketBuyOrderWithCost
   * @description create a market buy order by providing the symbol and cost
   * @see https://www.mexc.com/api-docs/spot-v3/spot-account-trade/new-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {float} cost how much you want to trade in units of the quote
   * currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createMarketBuyOrderWithCost(std::any symbol, std::any cost,
                               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("spot")),
                                     true))) {
                   throw NotSupported(toString(add(
                       this->id, std::string(" createMarketBuyOrderWithCost() "
                                             "supports spot orders only"))));
                 }
                 std::any req = ccxt::dict{
                     {std::string("cost"), cost},
                 };
                 return awaitValue(this->createOrder(
                     symbol, std::string("market"), std::string("buy"), 0,
                     std::any{}, this->extend(req, params)));
               })
        .share();
  }

